template.solver:
def solve(k):
    best = [0] * k
    for x in range(k - 1, 0, -1):
        g = -((-x * k) // (k - x))
        m = 0
        for y in range(g, k):
            if best[y] > m:
                m = best[y]
        best[x] = max(2, 1 + m)
    ans = 1
    for x in range(1, k):
        if best[x] > ans:
            ans = best[x]
    return ans
